parameters.functionCode:
// Extract and validate candidate data from webhook
const data = $input.first().body;

if (!data.candidateName || !data.candidateEmail) {
  throw new Error('Missing required fields: candidateName and candidateEmail');
}

return {
  candidateName: data.candidateName,
  candidateEmail: data.candidateEmail,
  position: data.position || 'Software Engineer',
  company: data.company || 'Our Company',
  interviewDate: data.interviewDate || new Date().toISOString().split('T')[0],
  interviewTime: data.interviewTime || '10:00 AM',
  timezone: data.timezone || 'EST',
  hrEmail: data.hrEmail || 'hr@company.com'
};

// Generate AI prompt for email content
const data = $input.first().json;

const prompt = `
Create a professional and friendly acceptance email for the following candidate:

Candidate Name: ${data.candidateName}
Position: ${data.position}
Company: ${data.company}
Interview Date: ${data.interviewDate}
Interview Time: ${data.interviewTime} ${data.timezone}

Please include:
1. Congratulations on advancing in the interview process
2. Interview details (date, time, timezone)
3. A brief note about what to expect
4. Contact information for questions
5. Professional closing

Make it warm, personal, and professional.`;

return {
  prompt: prompt,
  candidateName: data.candidateName,
  candidateEmail: data.candidateEmail,
  position: data.position,
  company: data.company,
  interviewDate: data.interviewDate,
  interviewTime: data.interviewTime,
  timezone: data.timezone,
  hrEmail: data.hrEmail
};

